// Bevy's default font (bevy_text's DEFAULT_FONT_DATA, src/FiraMono-subset.ttf of bevy_text 0.20.0: Fira Mono Medium,
// subset), inlined so a page's Bevy UI text is drawn in the face Bevy draws it in. Fira Mono is under the SIL Open Font
// License 1.1 (FiraMono-LICENSE beside this file). Generated: base64 of the file as shipped; do not edit.
export const BEVY_FONT_FAMILY = "Bevy Default Font";
const DATA = "";
/** the @font-face that names Bevy's default font BEVY_FONT_FAMILY */
export const bevyFontFace = () => `@font-face { font-family: "${BEVY_FONT_FAMILY}"; src: url("data:font/ttf;base64,${DATA}"); font-weight: 1 1000; }`;
